public interface Walkable {
    default void move() {
        System.out.println("Walking...");
    }
}

public interface Swimmable {
    default void move() {
        System.out.println("Swimming...");
    }
}

// Compilation error unless overridden: Class Amphibian inherits unrelated defaults for move()
public class Amphibian implements Walkable, Swimmable {
    @Override
    public void move() {
        // Explicitly resolving the diamond/collision problem
        Walkable.super.move();
        Swimmable.super.move();
    }
}
